        //CAD-M. (MAN)
        //Group  NC. WT_Auto * ME_Rate / 1000; ยกเว้น CAD-M.
        let DP_Cost;
        let ME_Cost;
        if ((row.attr('class') || '').toLowerCase().includes('nc.')) {
            DP_Cost = WT_Auto * DP_Rate / 1000;
            ME_Cost = WT_Auto * ME_Rate / 1000;

        }
        else {
            DP_Cost = WT_Man * DP_Rate / 1000;
            ME_Cost = WT_Man * ME_Rate / 1000;

